function today(): string {
  const d = new Date();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${month}-${day}`;
}

function showMoney(value: number | null | undefined): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value ?? 0);
}

function roundAway(value: number, digits: number): number {
  if (!Number.isFinite(value)) return 0;
  const factor = 10 ** digits;
  const scaled = value * factor;
  const sign = scaled < 0 ? -1 : 1;
  return (sign * Math.round(Math.abs(scaled))) / factor;
}

function num(raw: string): number | null {
  const text = raw.trim();
  if (!text) return null;
  const value = Number(text.replace(',', '.'));
  return Number.isFinite(value) ? value : null;
}

function textOrNull(raw: string): string | null {
  const text = raw.trim();
  return text.length === 0 ? null : text;
}

function dateOrNull(raw: string): string | null {
  const text = raw.trim();
  return text.length === 0 ? null : text;
}

function dec(value: number | null | undefined): string {
  if (value == null) return '0';
  return String(value);
}

function dateText(value: string | null | undefined): string {
  return value ? value.slice(0, 10) : '';
}

