function blockMessage(form: FormState): string {
  if ((form.maGd === '1' || form.maGd === '2') && form.maKh.trim().length === 0) return 'Bạn chưa nhập mã đối tượng';
  if (form.maNx.trim().length === 0) return 'Bạn chưa nhập tài khoản có';
  for (const line of form.lines) {
    if (line.tkVt.trim().length === 0) return 'Bạn chưa nhập tài khoản nợ';
  }
  return '';
}

function flag(value: boolean): number {
  return value ? 1 : 0;
}

function toWrite(form: FormState, mode: 'create' | 'copy' | 'edit'): Pn2AdvanceSettlementWrite {
  const sendKey = mode === 'edit';
  const lines: Pn2AdvanceSettlementWriteLine[] = form.lines.map(line => {
    const row: Pn2AdvanceSettlementWriteLine = {
      tkVt: textOrNull(line.tkVt),
      tienNt: num(line.tienNt),
      tien: num(line.tien),
      dienGiaii: textOrNull(line.dienGiaii),
      maVvI: textOrNull(line.maVvI),
      maHdI: textOrNull(line.maHdI),
      maPhiI: textOrNull(line.maPhiI),
      maTtlnI: textOrNull(line.maTtlnI),
      maTtcpI: textOrNull(line.maTtcpI),
      maBpI: textOrNull(line.maBpI),
    };
    if (sendKey && line.sttRec0.trim()) row.sttRec0 = line.sttRec0.trim();
    return row;
  });
  const taxLines: Pn2AdvanceSettlementWriteTaxLine[] = form.taxLines.map(line => {
    const row: Pn2AdvanceSettlementWriteTaxLine = {
      tkThueNo: textOrNull(line.tkThueNo),
      tkDu: textOrNull(line.tkDu),
      maKh: textOrNull(line.maKh),
      tThueNt: num(line.tThueNt),
      tThue: num(line.tThue),
      diaChi: textOrNull(line.diaChi),
      ngayCt0: dateOrNull(line.ngayCt0),
      soCt0: textOrNull(line.soCt0),
      soSeri0: textOrNull(line.soSeri0),
      maThue: textOrNull(line.maThue),
      thueSuat: num(line.thueSuat),
      tTienNt: num(line.tTienNt),
      tTien: num(line.tTien),
      tenKh: textOrNull(line.tenKh),
      maSoThue: textOrNull(line.maSoThue),
      tenVt: textOrNull(line.tenVt),
      soLuong: num(line.soLuong),
      giaNt: num(line.giaNt),
      gia: num(line.gia),
      ghiChu: textOrNull(line.ghiChu),
    };
    if (sendKey && line.sttRec0.trim()) row.sttRec0 = line.sttRec0.trim();
    return row;
  });
  return {
    maCt: 'PN2',
    maGd: form.maGd,
    maPost: form.maPost,
    maQuyen: textOrNull(form.maQuyen),
    ngayCt: dateOrNull(form.ngayCt),
    ngayLct: dateOrNull(form.ngayLct),
    soCt: textOrNull(form.soCt),
    soCt0: textOrNull(form.soCt0),
    soSeri0: textOrNull(form.soSeri0),
    ngayCt0: dateOrNull(form.ngayCt0),
    soLo: textOrNull(form.soLo),
    ngayLo: dateOrNull(form.ngayLo),
    maKh: textOrNull(form.maKh),
    ongBa: textOrNull(form.ongBa),
    diaChi: textOrNull(form.diaChi),
    maSoThue: textOrNull(form.maSoThue),
    dienGiai: textOrNull(form.dienGiai),
    tenKhVat: textOrNull(form.tenKhVat),
    diaChiVat: textOrNull(form.diaChiVat),
    maBpH: textOrNull(form.maBpH),
    maHsH: textOrNull(form.maHsH),
    maNx: textOrNull(form.maNx),
    maNt: textOrNull(form.maNt),
    tyGia: num(form.tyGia),
    mauBc: textOrNull(form.mauBc),
    suaThue: flag(form.suaThue),
    suaTkThue: flag(form.suaTkThue),
    maThue: textOrNull(form.maThue),
    thueSuat: num(form.thueSuat),
    tkThueNo: textOrNull(form.tkThueNo),
    tkThueCo: textOrNull(form.tkThueCo),
    hanTt: num(form.hanTt),
    lenhSo: textOrNull(form.lenhSo),
    lenhPo: textOrNull(form.lenhPo),
    lenhRo: textOrNull(form.lenhRo),
    lenhVt: textOrNull(form.lenhVt),
    lines,
    taxLines,
  };
}

function preview(form: FormState) {
  const tTienNt = roundAway(form.lines.reduce((sum, line) => sum + (num(line.tienNt) ?? 0), 0), 4);
  const tTien = roundAway(form.lines.reduce((sum, line) => sum + (num(line.tien) ?? 0), 0), 4);
  const tThueNt = roundAway(form.taxLines.reduce((sum, line) => sum + (num(line.tThueNt) ?? 0), 0), 4);
  const tThue = roundAway(form.taxLines.reduce((sum, line) => sum + (num(line.tThue) ?? 0), 0), 4);
  return {
    tTienNt,
    tTien,
    tThueNt,
    tThue,
    soHdGtgt: form.taxLines.length,
    tTtNt: roundAway(tTienNt + tThueNt, 4),
    tTt: roundAway(tTien + tThue, 4),
  };
}

const Pn2FormPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const mode = searchParams.get('mode');
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = Boolean(sttRec) && mode === 'view';
  const isCopy = !sttRec && copyFrom.length > 0;
  const isNew = !sttRec;
  const readOnly = isView;
  const [form, setForm] = useState<FormState>(emptyForm);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [missing, setMissing] = useState(false);
  const [selectedLine, setSelectedLine] = useState(-1);
  const [selectedTax, setSelectedTax] = useState(-1);
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({ message: LEAVE_MESSAGE });
  const { markDirty, markClean } = useDirtyTracking(isView ? undefined : onDirtyChange);

  useEffect(() => {
    const load = async () => {
      if (isNew && !isCopy) {
        setForm(emptyForm());
        setMissing(false);
        markClean();
        return;
      }
      setLoading(true);
      setError('');
      setMissing(false);
      try {
        const dto = await getPn2AdvanceSettlement(sttRec || copyFrom);
        setForm(formFromApi(dto, isCopy));
        markClean();
      } catch (err) {
        setMissing(true);
        setError(err instanceof Error && err.message ? err.message : 'Không tìm thấy phiếu thanh toán tạm ứng');
      } finally {
        setLoading(false);
      }
    };
    void load();
  }, [sttRec, copyFrom, isCopy, isNew, markClean]);

  const touch = (next: FormState) => {
    setForm(next);
    if (!readOnly) markDirty();
  };

  const setField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    touch({ ...form, [key]: value });
  };

  const setLine = (index: number, patch: Partial<LineState>) => {
    const lines = form.lines.map((line, i) => (i === index ? { ...line, ...patch } : line));
    touch({ ...form, lines });
  };

  const setTax = (index: number, patch: Partial<TaxState>) => {
    const taxLines = form.taxLines.map((line, i) => (i === index ? { ...line, ...patch } : line));
    touch({ ...form, taxLines });
  };

  const onBlurCustomer = async () => {
    const code = form.maKh.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenKh: '' }));
      return;
    }
    try {
      const res = await ktService.searchCustomers({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenKh: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurAccount = async () => {
    const code = form.maNx.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenNx: '' }));
      return;
    }
    try {
      const res = await ktService.searchAccounts({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenNx: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurTkVt = async (index: number) => {
    const code = form.lines[index]?.tkVt.trim() ?? '';
    if (!code) {
      setLine(index, { tenTkVt: '' });
      return;
    }
    try {
      const res = await ktService.searchAccounts({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({
        ...prev,
        lines: prev.lines.map((line, i) => (i === index ? { ...line, tenTkVt: hit?.name ?? '' } : line)),
      }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurTaxCustomer = async (index: number) => {
    const line = form.taxLines[index];
    if (!line) return;
    const code = line.maKh.trim();
    if (!code) {
      if (!line.tenKhTouched || line.tenKh.trim().length === 0) {
        setTax(index, { tenKh: '' });
      }
      return;
    }
    try {
      const res = await ktService.searchCustomers({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({
        ...prev,
        taxLines: prev.taxLines.map((row, i) => {
          if (i !== index) return row;
          if (row.tenKhTouched && row.tenKh.trim().length > 0) return row;
          return { ...row, tenKh: hit?.name ?? '' };
        }),
      }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onSave = async () => {
    const blocked = blockMessage(form);
    if (blocked) {
      setError(blocked);
      dispatchAppToast(dispatch, { type: 'error', message: blocked });
      return;
    }
    setSaving(true);
    setError('');
    try {
      const writeMode = isCopy ? 'copy' : isNew ? 'create' : 'edit';
      const body = toWrite(form, writeMode);
      const saved = isNew
        ? await createPn2AdvanceSettlement(body)
        : await updatePn2AdvanceSettlement(sttRec ?? '', body);
      markClean();
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu phiếu thanh toán tạm ứng' });
      navigate(`/kt/pn2/${saved.sttRec}`);
      if (!isNew) {
        const fresh = await getPn2AdvanceSettlement(saved.sttRec);
        setForm(formFromApi(fresh, false));
        markClean();
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const title = isView
    ? 'Xem phiếu thanh toán tạm ứng'
    : isNew
      ? 'Thêm phiếu thanh toán tạm ứng'
      : 'Sửa phiếu thanh toán tạm ứng';
  const totals = preview(form);
  const selectedStyle = { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' };

  return (
    <div className={df.page} data-testid="ct-pn2-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={readOnly}
        saving={saving}
        testIdPrefix="ct-pn2"
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedNavigate(() => navigate('/kt/pn2'))}
        onSave={missing || readOnly ? undefined : onSave}
      />
      <LeaveConfirmModal {...leaveConfirmModalProps} />
      {error && <div className={df.errorBanner}>{error}</div>}
      {loading && <div className={df.loading}>Đang tải...</div>}
      {!missing && !loading && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select label="Loại giao dịch" disabled={readOnly} data-testid="ct-pn2-field-maGd" value={form.maGd} options={[{ value: '1', label: 'Theo hóa đơn' }, { value: '2', label: 'Thanh toán tạm ứng' }]} onChange={event => setField('maGd', event.target.value)} />
              <Select label="Trạng thái" disabled={readOnly} data-testid="ct-pn2-field-maPost" value={form.maPost} options={[{ value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Hạch toán sổ cái' }]} onChange={event => setField('maPost', event.target.value)} />
              <div><label className={df.label}>Quyền số</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-maQuyen" value={form.maQuyen} onChange={event => setField('maQuyen', event.target.value)} /></div>
              <div><label className={df.label}>Ngày C.từ</label><Input disabled={readOnly} type="date" data-testid="ct-pn2-field-ngayCt" value={form.ngayCt} onChange={event => setField('ngayCt', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lập</label><Input disabled={readOnly} type="date" data-testid="ct-pn2-field-ngayLct" value={form.ngayLct} onChange={event => setField('ngayLct', event.target.value)} /></div>
              <div><label className={df.label}>Số C.từ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-soCt" value={form.soCt} onChange={event => setField('soCt', event.target.value)} /></div>
              <div><label className={df.label}>Số hóa đơn VAT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-soCt0" value={form.soCt0} onChange={event => setField('soCt0', event.target.value)} /></div>
              <div><label className={df.label}>Ngày hóa đơn VAT</label><Input disabled={readOnly} type="date" data-testid="ct-pn2-field-ngayCt0" value={form.ngayCt0} onChange={event => setField('ngayCt0', event.target.value)} /></div>
              <div><label className={df.label}>Số seri hóa đơn VAT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-soSeri0" value={form.soSeri0} onChange={event => setField('soSeri0', event.target.value)} /></div>
              <div><label className={df.label}>Số lô</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-soLo" value={form.soLo} onChange={event => setField('soLo', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lô</label><Input disabled={readOnly} type="date" data-testid="ct-pn2-field-ngayLo" value={form.ngayLo} onChange={event => setField('ngayLo', event.target.value)} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Đối tượng</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-maKh" value={form.maKh} onChange={event => setField('maKh', event.target.value)} onBlur={() => { void onBlurCustomer(); }} /></div>
              <div><label className={df.label}>Tên đối tượng</label><Input disabled data-testid="ct-pn2-field-tenKh" value={form.tenKh} onChange={() => undefined} /></div>
              <div><label className={df.label}>Người giao</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pn2-field-ongBa" value={form.ongBa} onChange={event => setField('ongBa', event.target.value)} /></div>
              <div><label className={df.label}>Địa chỉ</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pn2-field-diaChi" value={form.diaChi} onChange={event => setField('diaChi', event.target.value)} /></div>
              <div><label className={df.label}>Mã số thuế</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-maSoThue" value={form.maSoThue} onChange={event => setField('maSoThue', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Diễn giải</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pn2-field-dienGiai" value={form.dienGiai} onChange={event => setField('dienGiai', event.target.value)} /></div>
              <div><label className={df.label}>Tên khách VAT</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pn2-field-tenKhVat" value={form.tenKhVat} onChange={event => setField('tenKhVat', event.target.value)} /></div>
              <div><label className={df.label}>Địa chỉ VAT</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pn2-field-diaChiVat" value={form.diaChiVat} onChange={event => setField('diaChiVat', event.target.value)} /></div>
              <div><label className={df.label}>Bộ phận</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-maBpH" value={form.maBpH} onChange={event => touch({ ...form, maBpH: event.target.value, tenBpH: '' })} onBlur={() => { if (!form.maBpH.trim()) setForm(prev => ({ ...prev, tenBpH: '' })); }} /></div>
              <div><label className={df.label}>Tên bộ phận</label><Input disabled data-testid="ct-pn2-field-tenBpH" value={form.tenBpH} onChange={() => undefined} /></div>
              <div><label className={df.label}>Hồ sơ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-maHsH" value={form.maHsH} onChange={event => touch({ ...form, maHsH: event.target.value, tenHsH: '' })} onBlur={() => { if (!form.maHsH.trim()) setForm(prev => ({ ...prev, tenHsH: '' })); }} /></div>
              <div><label className={df.label}>Tên hồ sơ</label><Input disabled data-testid="ct-pn2-field-tenHsH" value={form.tenHsH} onChange={() => undefined} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tài khoản và tiền tệ</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tài khoản có</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-maNx" value={form.maNx} onChange={event => setField('maNx', event.target.value)} onBlur={() => { void onBlurAccount(); }} /></div>
              <div><label className={df.label}>Tên tài khoản có</label><Input disabled data-testid="ct-pn2-field-tenNx" value={form.tenNx} onChange={() => undefined} /></div>
              <div><label className={df.label}>Ngoại tệ</label><Input disabled={readOnly} maxLength={3} data-testid="ct-pn2-field-maNt" value={form.maNt} onChange={event => setField('maNt', event.target.value)} /></div>
              <div><label className={df.label}>Tỷ giá</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pn2-field-tyGia" value={form.tyGia} onChange={event => setField('tyGia', event.target.value)} /></div>
              <div><label className={df.label}>Mẫu báo cáo</label><Input disabled={readOnly} maxLength={10} data-testid="ct-pn2-field-mauBc" value={form.mauBc} onChange={event => setField('mauBc', event.target.value)} /></div>
              <div><label className={df.label}>Mã thuế</label><Input disabled={readOnly} maxLength={10} data-testid="ct-pn2-field-maThue" value={form.maThue} onChange={event => setField('maThue', event.target.value)} /></div>
              <div><label className={df.label}>Thuế suất</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pn2-field-thueSuat" value={form.thueSuat} onChange={event => setField('thueSuat', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế nợ (header)</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-tkThueNo" value={form.tkThueNo} onChange={event => setField('tkThueNo', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế có</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-tkThueCo" value={form.tkThueCo} onChange={event => setField('tkThueCo', event.target.value)} /></div>
              <div><label className={df.label}>Hạn thanh toán</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pn2-field-hanTt" value={form.hanTt} onChange={event => setField('hanTt', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh số</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-lenhSo" value={form.lenhSo} onChange={event => setField('lenhSo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh PO</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-lenhPo" value={form.lenhPo} onChange={event => setField('lenhPo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh RO</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-lenhRo" value={form.lenhRo} onChange={event => setField('lenhRo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh VT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pn2-field-lenhVt" value={form.lenhVt} onChange={event => setField('lenhVt', event.target.value)} /></div>
              <Checkbox label="Sửa thuế" disabled={readOnly} data-testid="ct-pn2-field-suaThue" checked={form.suaThue} onChange={event => setField('suaThue', event.target.checked)} />
              <Checkbox label="Sửa TK thuế" disabled={readOnly} data-testid="ct-pn2-field-suaTkThue" checked={form.suaTkThue} onChange={event => setField('suaTkThue', event.target.checked)} />
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tổng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tổng Ps NT</label><Input disabled data-testid="ct-pn2-field-tTienNt" value={showMoney(totals.tTienNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tổng Phát sinh</label><Input disabled data-testid="ct-pn2-field-tTien" value={showMoney(totals.tTien)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tiền thuế NT</label><Input disabled data-testid="ct-pn2-field-tThueNt" value={showMoney(totals.tThueNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tiền thuế</label><Input disabled data-testid="ct-pn2-field-tThue" value={showMoney(totals.tThue)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Số HĐ GTGT</label><Input disabled data-testid="ct-pn2-field-soHdGtgt" value={String(totals.soHdGtgt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Thanh toán NT</label><Input disabled data-testid="ct-pn2-field-tTtNt" value={showMoney(totals.tTtNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Thanh toán</label><Input disabled data-testid="ct-pn2-field-tTt" value={showMoney(totals.tTt)} onChange={() => undefined} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng</h2>
            {!readOnly && (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-pn2-line-add-btn" onClick={() => { touch({ ...form, lines: [...form.lines, emptyLine()] }); setSelectedLine(form.lines.length); }}>Thêm dòng</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-pn2-line-remove-btn" disabled={selectedLine < 0} onClick={() => { touch({ ...form, lines: form.lines.filter((_, i) => i !== selectedLine) }); setSelectedLine(-1); }}>Xóa dòng</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pn2-line-grid">
                <thead>
                  <tr>
                    <th>Tk nợ</th>
                    <th>Tên tài khoản</th>
                    <th>Nguyên tệ</th>
                    <th>Thành tiền</th>
                    <th>Diễn giải</th>
                    <th>V.Việc</th>
                    <th>Hợp đồng</th>
                    <th>khoản mục</th>
                    <th>Trung tâm lợi nhuận</th>
                    <th>Trung tâm chi phí</th>
                    <th>Phòng ban</th>
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, i) => (
                    <tr key={i} aria-selected={i === selectedLine} style={i === selectedLine ? selectedStyle : undefined} onClick={() => setSelectedLine(i)}>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-tkVt`} value={line.tkVt} onChange={event => setLine(i, { tkVt: event.target.value })} onBlur={() => { void onBlurTkVt(i); }} /></td>
                      <td><Input disabled data-testid={`ct-pn2-line-${i}-tenTkVt`} value={line.tenTkVt} onChange={() => undefined} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-line-${i}-tienNt`} value={line.tienNt} onChange={event => setLine(i, { tienNt: event.target.value })} /></td>
                      <td><Input disabled data-testid={`ct-pn2-line-${i}-tien`} value={line.tien} onChange={() => undefined} /></td>
                      <td><Input disabled={readOnly} maxLength={200} data-testid={`ct-pn2-line-${i}-dienGiaii`} value={line.dienGiaii} onChange={event => setLine(i, { dienGiaii: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-maVvI`} value={line.maVvI} onChange={event => setLine(i, { maVvI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-maHdI`} value={line.maHdI} onChange={event => setLine(i, { maHdI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-maPhiI`} value={line.maPhiI} onChange={event => setLine(i, { maPhiI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-maTtlnI`} value={line.maTtlnI} onChange={event => setLine(i, { maTtlnI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-maTtcpI`} value={line.maTtcpI} onChange={event => setLine(i, { maTtcpI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-line-${i}-maBpI`} value={line.maBpI} onChange={event => setLine(i, { maBpI: event.target.value })} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Thuế GTGT đầu vào</h2>
            {!readOnly && (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-pn2-tax-add-btn" onClick={() => { touch({ ...form, taxLines: [...form.taxLines, emptyTax()] }); setSelectedTax(form.taxLines.length); }}>Thêm dòng thuế</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-pn2-tax-remove-btn" disabled={selectedTax < 0} onClick={() => { touch({ ...form, taxLines: form.taxLines.filter((_, i) => i !== selectedTax) }); setSelectedTax(-1); }}>Xóa dòng thuế</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pn2-tax-grid">
                <thead>
                  <tr>
                    <th>TK thuế nợ</th>
                    <th>Tk đối ứng</th>
                    <th>Đối tượng</th>
                    <th>Tiền thuế NT</th>
                    <th>Tiền thuế</th>
                    <th>Địa chỉ</th>
                    <th>Ngày hóa đơn VAT</th>
                    <th>Số hóa đơn VAT</th>
                    <th>Số seri hóa đơn VAT</th>
                    <th>Mã thuế</th>
                    <th>Thuế suất</th>
                    <th>Tiền hàng NT</th>
                    <th>Tiền hàng</th>
                    <th>Tên khách</th>
                    <th>Mã số thuế</th>
                    <th>Tên hàng</th>
                    <th>Số lượng</th>
                    <th>Giá NT</th>
                    <th>Giá</th>
                    <th>Ghi chú</th>
                  </tr>
                </thead>
                <tbody>
                  {form.taxLines.map((line, j) => (
                    <tr key={j} aria-selected={j === selectedTax} style={j === selectedTax ? selectedStyle : undefined} onClick={() => setSelectedTax(j)}>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-tkThueNo`} value={line.tkThueNo} onChange={event => setTax(j, { tkThueNo: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-tkDu`} value={line.tkDu} onChange={event => setTax(j, { tkDu: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-maKh`} value={line.maKh} onChange={event => setTax(j, { maKh: event.target.value })} onBlur={() => { void onBlurTaxCustomer(j); }} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-tThueNt`} value={line.tThueNt} onChange={event => setTax(j, { tThueNt: event.target.value })} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-tThue`} value={line.tThue} onChange={event => setTax(j, { tThue: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={200} data-testid={`ct-pn2-tax-${j}-diaChi`} value={line.diaChi} onChange={event => setTax(j, { diaChi: event.target.value })} /></td>
                      <td><Input disabled={readOnly} type="date" data-testid={`ct-pn2-tax-${j}-ngayCt0`} value={line.ngayCt0} onChange={event => setTax(j, { ngayCt0: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-soCt0`} value={line.soCt0} onChange={event => setTax(j, { soCt0: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-soSeri0`} value={line.soSeri0} onChange={event => setTax(j, { soSeri0: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-maThue`} value={line.maThue} onChange={event => setTax(j, { maThue: event.target.value })} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-thueSuat`} value={line.thueSuat} onChange={event => setTax(j, { thueSuat: event.target.value })} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-tTienNt`} value={line.tTienNt} onChange={event => setTax(j, { tTienNt: event.target.value })} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-tTien`} value={line.tTien} onChange={event => setTax(j, { tTien: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={200} data-testid={`ct-pn2-tax-${j}-tenKh`} value={line.tenKh} onChange={event => setTax(j, { tenKh: event.target.value, tenKhTouched: true })} /></td>
                      <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pn2-tax-${j}-maSoThue`} value={line.maSoThue} onChange={event => setTax(j, { maSoThue: event.target.value })} /></td>
                      <td><Input disabled={readOnly} maxLength={200} data-testid={`ct-pn2-tax-${j}-tenVt`} value={line.tenVt} onChange={event => setTax(j, { tenVt: event.target.value })} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-soLuong`} value={line.soLuong} onChange={event => setTax(j, { soLuong: event.target.value })} /></td>
                      <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pn2-tax-${j}-giaNt`} value={line.giaNt} onChange={event => setTax(j, { giaNt: event.target.value })} /></td>
                      <td><Input disabled data-testid={`ct-pn2-tax-${j}-gia`} value={line.gia} onChange={() => undefined} /></td>
                      <td><Input disabled={readOnly} maxLength={200} data-testid={`ct-pn2-tax-${j}-ghiChu`} value={line.ghiChu} onChange={event => setTax(j, { ghiChu: event.target.value })} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <span className={df.totalLabel}>Thanh toán</span>
            <span className={df.totalValue}>{showMoney(totals.tTt)}</span>
          </div>
        </>
      )}
    </div>
  );
};

export default Pn2FormPage;
